const ExcelJS = require('exceljs');

async function main() {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'Pi Agent';
  workbook.created = new Date();

  const sheet = workbook.addWorksheet('Extracted Text');

  // Define columns
  sheet.columns = [
    { header: 'Source', key: 'source', width: 25 },
    { header: 'Extracted Text', key: 'text', width: 70 },
  ];

  // Style the header row
  sheet.getRow(1).font = { bold: true, size: 12 };
  sheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FF4472C4' },
  };
  sheet.getRow(1).font = { bold: true, size: 12, color: { argb: 'FFFFFFFF' } };

  // Add extracted text data
  sheet.addRow({ source: 'pdftotext (Text Extraction)', text: 'Employee Handbook' });
  sheet.addRow({ source: '', text: 'Welcome to the company. This handbook outlines our policies.' });
  sheet.addRow({});
  sheet.addRow({ source: 'Tesseract (OCR)', text: 'Employee Handbook' });
  sheet.addRow({ source: '', text: 'Welcome to the company. This handbook outlines our policies.' });

  // Auto-fit row heights with wrap
  sheet.getColumn('text').alignment = { wrapText: true, vertical: 'top' };
  sheet.getColumn('source').alignment = { vertical: 'top' };

  const outputPath = '/workspace/testbed/docs/handbook_extracted.xlsx';
  await workbook.xlsx.writeFile(outputPath);
  console.log(`Excel file created: ${outputPath}`);
}

main().catch(console.error);

